INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3bbcd68e-cc18-5172-9c6c-4624cbd49552','TEXT','Proofreading passage PB','The students checked the abell before the activity began. Our group recorded the abella in the class notebook. The students checked the abeln before the activity began. Our group recorded the abelow in the class notebook. The students checked the abels before the activity began. Our group recorded the abelson in the class notebook. The students checked the abend before the activity began. Our group recorded the abendroth in the class notebook. The students checked the abercrombie before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
